# dot_product :: ([1,2,3], [4,5,6])
def dot_product(a, b):
    return sum(x * y for x, y in zip(a, b))

if __name__ == '__main__':
    print(dot_product(([1,2,3], [4,5,6])))

# dot_product :: ([0,1], [1,0])
def dot_product(a, b):
    return sum(x * y for x, y in zip(a, b))

if __name__ == '__main__':
    print(dot_product(([0,1], [1,0])))
